import { actionRef, eventRef, queryRef, ServiceClient } from "@stackra/clients";
import { HttpMethod } from "@stackra/contracts";
import { z } from "@stackra/schema";

/** pricing — transport: rpc. */
export const Pricing = {
  queries: {
    Quote: queryRef("pricing.price.quote", {
      input: z.object({
        market: z.string(),
        lines: z.array(z.object({ variantId: z.string(), quantity: z.number().int() })),
      }),
      output: z.object({
        currency: z.string(),
        lines: z.array(
          z.object({
            variantId: z.string(),
            quantity: z.number().int(),
            unitPriceMinor: z.number().int(),
          }),
       ),
      }),
      http: { method: HttpMethod.Post, path: "/prices/quote" },
    }),
  },
} as const;

/** payments — transport: rpc; both actions run under the on-behalf-of chain. */
export const Payments = {
  actions: {
    Authorize: actionRef("payments.payment.authorize", {
      input: z.object({
        reference: z.string(),
        amountMinor: z.number().int(),
        currency: z.string(),
      }),
      output: z.object({ paymentId: z.string(), clientSecret: z.string() }),
      http: { method: HttpMethod.Post, path: "/payments" },
    }),
    Void: actionRef("payments.payment.void", {
      input: z.object({ paymentId: z.string() }),
      output: z.object({ paymentId: z.string() }),
      http: { method: HttpMethod.Put, path: "/payments/:paymentId/void" },
    }),
  },
  events: {
    /** `reference` is whatever the authorizer passed (an order id for orders). */
    PaymentCaptured: eventRef("payments.payment.captured.v1", {
      payload: z.object({
        paymentId: z.string(),
        reference: z.string(),
        amountMinor: z.number().int(),
        currency: z.string(),
      }),
    }),
    /** `reason` is the provider's snake_case code. */
    PaymentFailed: eventRef("payments.payment.failed.v1", {
      payload: z.object({ paymentId: z.string(), reference: z.string(), reason: z.string() }),
    }),
  },
} as const;

/** notifications — transport: in-process in staging (deployable `core`), rpc in production. */
export const Notifications = {
  actions: {
    Send: actionRef("messages.message.send", {
      input: z.object({
        mail: z.string(),
        to: z.object({ principalId: z.string() }),
        subject: z.string(),
        html: z.string(),
        text: z.string(),
      }),
      output: z.object({ messageId: z.string() }),
      http: { method: HttpMethod.Post, path: "/messages" },
    }),
  },
} as const;

/** Calls into the pricing service; `price.quote.call(input)` is authoritative now. */
export class PricingClient extends ServiceClient {
  /** The `price` resource. */
  readonly price = { quote: this.member(Pricing.queries.Quote) };
}

/** Calls into the payments service; `void` is also `.queue(input)` (a command). */
export class PaymentsClient extends ServiceClient {
  /** The `payment` resource. */
  readonly payment = {
    authorize: this.member(Payments.actions.Authorize),
    void: this.member(Payments.actions.Void),
  };
}

/** Calls into the notifications service; the `notifications` Mailer driver uses `.queue`. */
export class NotificationsClient extends ServiceClient {
  /** The `message` resource. */
  readonly message = { send: this.member(Notifications.actions.Send) };
}
